/// Look up the delays of a skill at the given level.
///
/// Returns `None` for skills without any server-side delay (or skills that
/// are not in the server data at all); callers fall back to their defaults.
pub fn skill_delays(skill_id: SkillId, level: u16) -> Option<&'static SkillDelays> {
    let index = SKILL_DELAYS.binary_search_by_key(&skill_id.0, |row| row.skill_id).ok()?;
    let levels = SKILL_DELAYS[index].levels;
    let level_index = usize::from(level).saturating_sub(1);
    levels.get(level_index).or_else(|| levels.last())
}

#[cfg(test)]
mod tests {
    use ragnarok_packets::SkillId;

    use super::{SKILL_DELAYS, skill_delays};

    #[test]
    fn table_is_sorted_and_non_empty() {
        assert!(!SKILL_DELAYS.is_empty());
        assert!(SKILL_DELAYS.windows(2).all(|pair| pair[0].skill_id < pair[1].skill_id));
        assert!(SKILL_DELAYS.iter().all(|row| !row.levels.is_empty()));
    }

    #[test]
    fn known_skills_have_their_delays() {
        // AL_HEAL (28): 1000 ms after-cast act delay, no cast time.
        let heal = skill_delays(SkillId(28), 1).expect("AL_HEAL should be in the table");
        assert_eq!(heal.aftercast_act_ms, 1000);
        assert_eq!(heal.total_cast_ms(), 0);

        // AL_INCAGI (29) has a 1000 ms cast time.
        let incagi = skill_delays(SkillId(29), 10).expect("AL_INCAGI should be in the table");
        assert_eq!(incagi.cast_ms, 1000);
        assert_eq!(incagi.total_cast_ms(), 1000);

        // MG_FIREBOLT (19) scales its cast time with the skill level.
        let bolt_1 = skill_delays(SkillId(19), 1).expect("MG_FIREBOLT should be in the table");
        let bolt_10 = skill_delays(SkillId(19), 10).expect("MG_FIREBOLT should be in the table");
        assert!(bolt_10.cast_ms > bolt_1.cast_ms);
    }

    #[test]
    fn unknown_skills_and_levels_fall_back_safely() {
        assert!(skill_delays(SkillId(65_000), 1).is_none());
        // A level above the maximum uses the last entry instead of panicking.
        let heal_high = skill_delays(SkillId(28), 99).expect("AL_HEAL should be in the table");
        let heal_max = skill_delays(SkillId(28), 10).expect("AL_HEAL should be in the table");
        assert_eq!(heal_high, heal_max);
    }
}
